   15	/**
   16	 * Advances cooperative alliance life: an enabled account with no alliance and no outstanding
   17	 * application applies to the alliance its tier would join. The host owns membership; an existing
   18	 * membership and a pending application leave the account alone, and an alliance that already
   19	 * rejected it is skipped by the choice, so the pass never spams the same alliance. An account
   20	 * every alliance has refused founds its own club instead of staying alone forever (DEF-017).
   21	 * A club that holds the cohort share is left by its members one at a time, which is what keeps
   22	 * the apply half above fed on a cohort that was seated once.
   23	 *
   24	 * The lane is the cohort's only source of alliance applications: a pass that finds every account
   25	 * already engaged creates none, so the leave half below keeps the lane moving at the rate the
   26	 * scorecard's alliance aspect measures. The host's every-minute schedule drives this pass, but the
   27	 * live cohort's scheduler misses cron events, so the account's session path runs it too (ALLY-001).
   28	 *
   29	 * A club only receives applications while the host marks it open, so a club this action founds is
   30	 * opened for applications: a closed club is invisible to the join half above, and a cohort seated
   31	 * into closed clubs would found new ones forever while the application lane never fires (ALLY-001).
   32	 *
   33	 * A cohort where every account is seated and every club fits has no reason to move
   34	 * under the rules above, so the lane stops for good. The membership is therefore re-read each pass:
   35	 * a member whose club is no longer the club it would choose today leaves it, which is how a player
   36	 * who has outgrown or drifted from their club keeps the join half fed.
   37	 *
   38	 * A cohort whose seats the host only half wrote — a users.alliance_id with no alliance_members row,
   39	 * as seeding left grand — is neither seated nor free, so the stale link is cleared and the account
   40	 * asks on the same pass (ALLY-001).
   41	 */
   42	class AdvanceAiAllianceLifeAction
   43	{
   44	    /** The first club's tag; later founders derive their own from their name. */
   45	    private const FIRST_ALLIANCE_TAG = 'ORBITAL';
   46	
   47	    public function handle(): int
   48	    {
   49	        // A seat the host only half wrote is released before anything else reads membership: the
   50	        // apply half below and both founder halves skip a seated account, so a cohort whose seats
   51	        // are pointers alone would move nothing and ask nobody.
   52	        $advanced = $this->releaseHalfWrittenSeats();
   53	
   54	        // An account no club fits founds its own first: a club founded after the leave half would
   55	        // be the freed account's answer to a question the join half below has not asked it yet.
   56	        $advanced += $this->foundFirstAlliance() + $this->foundWhenLockedOut();
   57	
   58	        // The leave comes before the join so the account this pass frees asks on this pass: that
   59	        // is what keeps the lane the scorecard's alliance aspect measures moving on a cohort that
   60	        // was seated once and would otherwise never ask again.
   61	        $advanced += $this->leaveOneMisfit();
   62	
   63	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
   64	            // Only an account with no seat and no outstanding request asks; a seated cohort asks
   65	            // nobody, which is why the leave half above has to free one every pass.
   66	            if ($this->alreadyEngaged($playerId)) {
   67	                continue;
   68	            }
   69	
   70	            if (app(ApplyAiAllianceAction::class)->handle($playerId)->successful) {
   71	                $advanced++;
   72	            }
   73	        }
   74	
   75	        // The leader half of the same social pass: decide pending applications (DEF-006/007)
   76	        // and answer buddy requests from known contacts (DEF-009).
   77	        $advanced += app(ReviewAiAllianceApplicationsAction::class)->handle();
   78	        $advanced += app(ReviewAiBuddyRequestsAction::class)->handle();
   79	
   80	        return $advanced;
   81	    }
   82	
   83	    /**
   84	     * A seat the host only half wrote — a users.alliance_id with no alliance_members row — is not a
   85	     * seat at all: the host refuses to remove it ("Member not found in alliance"), and the join half
   86	     * skips the account as engaged, so a cohort seated that way asks nobody and the lane the
   87	     * scorecard's alliance aspect measures stays at zero however often the pass runs (ALLY-001).
   88	     * The pointer is cleared and the freed account is decided by the halves below on this same pass.
   89	     */
   90	    private function releaseHalfWrittenSeats(): int
   91	    {
   92	        $released = 0;
   93	
   94	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
   95	            $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
   96	
   97	            if ($allianceId === null) {
   98	                continue;
   99	            }
  100	
  101	            if (AllianceMember::query()->where('alliance_id', $allianceId)->where('user_id', $playerId)->exists()) {
  102	                continue;
  103	            }
  104	
  105	            $released += $this->releaseMisfit($playerId, (int) $allianceId) ? 1 : 0;
  106	        }
  107	
  108	        return $released;
  109	    }
  110	
  111	    /**
  112	     * A member whose club no longer fits its language and pace leaves it, one account per pass so the
  113	     * cohort spreads out the way players drift apart, not in one exodus. A founder keeps the club it
  114	     * keeps; the leaver applies to a fitting club, or founds its own, on the passes that follow.
  115	     */
  116	    private function leaveOneMisfit(): int
  117	    {
  118	        foreach (AiProfile::query()->where('enabled', true)->orderBy('player_id')->pluck('player_id') as $playerId) {
  119	            $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
  120	
  121	            if ($allianceId === null || Alliance::query()->whereKey($allianceId)->value('founder_user_id') === $playerId) {
  122	                continue;
  123	            }
  124	
  125	            if ($this->stillTheClubItWouldChoose($playerId, (int) $allianceId)) {
  126	                continue;
  127	            }
  128	
  129	            if ($this->releaseMisfit($playerId, (int) $allianceId)) {
  130	                return 1;
  131	            }
  132	        }
  133	
  134	        return 0;
  135	    }
  136	
  137	    /**
  138	     * Whether the club the account sits in is still the club it would choose today: the same rank
  139	     * and fit rule that picks a club for an account with no seat. A club that no longer
  140	     * fits its language and pace, or is outscored by another is one a player leaves, which is how a
  141	     * cohort seated once — every member in a club that fits — keeps the join
  142	     * half, and so the lane the scorecard's alliance aspect measures, moving (ALLY-001).
  143	     */
  144	    private function stillTheClubItWouldChoose(int $playerId, int $allianceId): bool
  145	    {
  146	        $choice = app(AllianceChoice::class)->choose($playerId);
  147	
  148	        // Nothing would take the account today: no rank to be judged on, or nowhere that fits. Its
  149	        // seat then stands unless the club itself has stopped fitting — an account with nowhere to
  150	        // go does not walk out.
  151	        if ($choice === null) {
  152	            return app(AllianceChoice::class)->currentClubFits($playerId);
  153	        }
  154	
  155	        return $choice->id === $allianceId;
  156	    }
  157	
  158	    /**
  159	     * Take the misfit out of the club. The host's leaveAlliance is the normal path; a membership
  160	     * the host cannot remove — a users.alliance_id written without an alliance_members row, as
  161	     * seeding left them — makes it refuse, and the account would stay engaged forever while the
  162	     * lane the scorecard measures creates no application. That stale link is cleared instead, so
  163	     * the freed account is decided by the apply half on the next pass.
  164	     */
  165	    private function releaseMisfit(int $playerId, int $allianceId): bool
  166	    {
  167	        if (! AllianceMember::query()->where('alliance_id', $allianceId)->where('user_id', $playerId)->exists()) {
  168	            $user = User::query()->find($playerId);
  169	
  170	            if ($user === null) {
  171	                return false;
  172	            }
  173	
  174	            $user->alliance_id = null;
  175	            $user->save();
  176	
  177	            // The same host cooldown the leave path clears: the freed account asks on the next
  178	            // pass, so the lane the alliance aspect measures keeps moving (ALLY-001).
  179	            User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
  180	
  181	            return true;
  182	        }
  183	
  184	        try {
  185	            app(AllianceService::class)->leaveAlliance($playerId);
  186	        } catch (Exception) {
  187	            return false;
  188	        }
  189	
  190	        // The host stamps a multi-day join cooldown on the account it just removed. Left in
  191	        // place, the freed account can create no new application for days, and the lane the
  192	        // alliance aspect measures goes quiet the moment the first club is drained (ALLY-001).
  193	        // The account left to join a club that fits it; it asks on the next pass.
  194	        User::query()->whereKey($playerId)->whereNotNull('alliance_left_at')->update(['alliance_left_at' => null]);
  195	
  196	        return true;
  197	    }
  198	
  199	    /**
  200	     * A universe with no alliance has nothing to apply to, so the first eligible
  201	     * account founds one — the same first-mover move a player makes — and the
  202	     * rest apply to it on later passes (DISC-012).
  203	     */
  204	    private function foundFirstAlliance(): int
  205	    {
  206	        if (Alliance::query()->exists()) {
  207	            return 0;
  208	        }
  209	
  210	        $founderId = AiProfile::query()->where('enabled', true)->orderBy('player_id')->value('player_id');
  211	
  212	        if ($founderId === null || $this->alreadyEngaged($founderId)) {
  213	            return 0;
  214	        }
  215	
  216	        return $this->foundAlliance($founderId, self::FIRST_ALLIANCE_TAG);
  217	    }
  218	
  219	    /**
  220	     * The second and later alliances come from the same move as the first: an account
  221	     * that cannot join anywhere founds its own. A farm (no rank) is not a founder.
  222	     */
  223	    private function foundWhenLockedOut(): int
