208	/**
209	 * Percentage points left under the 20% failure ceiling, so the floor of 0 reads the same way as
210	 * every other aspect: a negative number fails.
211	 */
212	function failure_headroom(array $players, CarbonImmutable $since): int
213	{
214	    $finished = DB::table('ai_work_items')->whereIn('player_id', $players)->where('updated_at', '>=', $since)
215	        ->whereIn('state', [AiWorkState::Completed->value, AiWorkState::Failed->value])
216	        ->selectRaw('state, count(*) as total')->groupBy('state')->pluck('total', 'state');
217	    $total = (int) $finished->sum();
218	
219	    return $total === 0 ? -1 : 20 - (int) round(100 * (int) ($finished[AiWorkState::Failed->value] ?? 0) / $total);
220	}
